/// <summary>
/// When creating a new deal and METInvoiceConsolidationByRebateType is modified, make the METVendAccount mandatory
/// </summary>
/// <param name="sender">FormDataObject METInvoiceConsolidationByRebateType</param>
/// <param name="e">FormDataFieldEventArgs</param>
[FormDataFieldEventHandler(formDataFieldStr(TAMRebateDealNewDeal, TAMRebateDeal, METInvoiceConsolidationByRebateType), FormDataFieldEventType::Modified),
 SuppressBPWarning('BPParameterNotUsed', '@MET:BPParameterNotUsedMessage')]
public static void METInvoiceConsolidationByRebateType_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource rebateDeal_ds = sender.datasource();
    TAMRebateDeal  rebateDeal = rebateDeal_ds.cursor();
    TAMRebatePostingId rebatePostingId = rebateDeal.RebatePostingId;

    FormRun formRun = rebateDeal_ds.formRun();

    const str enableFields = 'enableFields';

    if (SysFormRun::hasMethod(formRun, identifierStr(enableFields)))
    {
        formRun.enableFields();
    }

    // RebatePostingId gets cleared in TAMRebateDealGUPExtensionHelper\setUpGUPUIForRebateDealNewDealForm
    rebateDeal = rebateDeal_ds.cursor();
    rebateDeal.RebatePostingId = rebatePostingId;
}
